package com.muxigame.city;
import java.util.*;
import net.minecraft.gametest.framework.*;
import net.neoforged.neoforge.gametest.*;

@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public class CityTestsRelief {
 static RuralRules.Family unemployed(CityTestsScale.Fixture f){var home=f.r.state.families.values().stream().filter(v->v.city.equals(f.city.id)).findFirst().orElseThrow();for(var id:home.members)RuralSuccession.setRole(f.r.state.people.get(id),RuralRules.Role.NONE);for(var site:f.r.state.sites.values())if(home.members.contains(site.worker))site.worker=null;for(var house:f.city.housing.houses.values())house.workers.removeAll(home.members);for(var b:f.t.state.businesses.values())if(home.members.contains(b.worker))b.closing=true;for(var stock:f.r.stocks(home.id)){stock.wheat=stock.bread=0;RuralMeat.clear(stock);}return home;}
 @GameTest(template="empty") public static void unemploymentFoodMovesRealStockOnceAndKeepsExpiry(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);var home=unemployed(f);var policy=CityRelief.policy(f.s,f.city.id);policy.capacity=100;f.city.works.resources.put("minecraft:bread",100);f.city.works.foodAges.computeIfAbsent("minecraft:bread",k->new FoodAge.State()).add(100,.5);CityRelief.track(f.s,f.city.id);long cash=f.t.money(f.s),grain=f.t.grain(f.s);int got=CityRelief.give(f.s,home);h.assertTrue(got==4&&f.city.works.resources.get("minecraft:bread")==96&&f.t.grain(f.s)==grain&&f.t.money(f.s)==cash,"Actual public stock fills only this household's next meal deficit");h.assertTrue(f.r.stocks(home.id).getFirst().ages[1].groups.getFirst().age==FoodAge.SCALE/2,"Relief does not renew food age");RuralRules.take(f.r.stocks(home.id),true,4);h.assertTrue(CityRelief.give(f.s,home)==0&&policy.given==4,"Repeated same settlement cannot claim another meal");}h.succeed();}
 @GameTest(template="empty") public static void tenPercentEmergencyOverridesOrdinaryUnemploymentAid(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);var home=unemployed(f);CityRelief.policy(f.s,f.city.id).capacity=100;f.city.works.resources.put("minecraft:bread",9);CityRelief.track(f.s,f.city.id);h.assertTrue(CityRelief.give(f.s,home)==0&&f.city.works.resources.get("minecraft:bread")==9,"Below ten percent, ordinary relief cannot consume the protected reserve");h.assertTrue(CityRelief.purchase(f.s,f.village.id)==0&&!f.t.state.relief.containsKey(f.village.id),"Rural head private food never becomes a public granary");}h.succeed();}
 @GameTest(template="empty") public static void sevenDayExpiryKeepsHousedResidentsAndOnlyDisplacesHomeless(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);var home=unemployed(f);CityRelief.policy(f.s,f.city.id).capacity=100;f.city.works.resources.put("minecraft:bread",100);CityRelief.track(f.s,f.city.id);f.r.state.simulationTicks=6*24000;CityRelief.track(f.s,f.city.id);h.assertTrue(CityRelief.give(f.s,home)==4,"Six-day continuous unemployment remains within aid window");RuralRules.take(f.r.stocks(home.id),true,4);f.r.state.simulationTicks=7*24000;CityRelief.track(f.s,f.city.id);h.assertTrue(CityRelief.give(f.s,home)==0&&home.members.stream().allMatch(id->f.r.state.people.get(id).role==RuralRules.Role.NONE),"Seven-day expiry stops food; legal residents retain citizen status");for(var house:f.city.housing.houses.values())house.residents.removeAll(home.members);CityRelief.track(f.s,f.city.id);h.assertTrue(home.members.stream().allMatch(id->f.r.state.people.get(id).role==RuralRules.Role.VAGRANT),"Only no legal home at expiry becomes vagrant, without changing assets");}h.succeed();}
 @GameTest(template="empty") public static void rebindingWithoutWorkCannotRenewSevenDayClock(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);var home=unemployed(f);var id=home.members.getFirst();var person=f.r.state.people.get(id);var business=f.t.state.businesses.values().stream().filter(b->id.equals(b.worker)).findFirst().orElseThrow();var site=f.r.state.sites.get(RuralSettlement.key(f.city.id,business.site));CityRelief.track(f.s,f.city.id);f.r.state.simulationTicks=2*24000;site.worker=id;business.closing=false;RuralSuccession.setRole(person,RuralRules.Role.PROCUREMENT);CityRelief.track(f.s,f.city.id);h.assertTrue(f.t.state.unemployment.get(id).since==0,"Rebinding and changing a role without work does not reset aid");person.totalWorkingTicks+=1200;CityRelief.track(f.s,f.city.id);h.assertTrue(f.t.state.unemployment.get(id).since==-1,"Real earned work ends the unemployment spell");site.worker=null;RuralSuccession.setRole(person,RuralRules.Role.NONE);f.r.state.simulationTicks+=600;CityRelief.track(f.s,f.city.id);h.assertTrue(f.t.state.unemployment.get(id).since==2*24000+600,"A genuinely new unemployment spell starts at its actual date");}h.succeed();}
 @GameTest(template="empty") public static void publicReservePurchasesOnlyCheapAvailableBreadAndProtectsPayroll(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);for(var b:f.t.state.businesses.values())if(b.city.equals(f.city.id)&&b.kind.equals("urban_farmer"))b.listed[0].add(100,0);var seller=f.t.state.businesses.values().stream().filter(b->b.kind.equals("baker")).findFirst().orElseThrow();seller.listed[1].add(20,2000);seller.listed[1].freshness.groups.getFirst().age=FoodAge.SCALE/2;long grain=f.t.grain(f.s),cash=f.t.money(f.s);int bought=CityRelief.purchase(f.s,f.city.id);h.assertTrue(bought==10&&f.city.works.resources.get("minecraft:bread")==10&&seller.listed[1].count==10,"Finite buyer buys one daytime segment from actual private inventory");h.assertTrue(f.t.grain(f.s)==grain&&f.t.money(f.s)==cash&&f.e.balance(CityEconomy.treasury(f.city.id))>=3*CityCurrency.payroll(f.s,f.city.id),"No free food, money or unpaid payroll");h.assertTrue(CityRelief.purchase(f.s,f.city.id)==0&&f.city.works.foodAges.get("minecraft:bread").groups.getFirst().age==FoodAge.SCALE/2,"Purchase is once per segment and preserves expiry");}h.succeed();}
}
